type Date struct {
    time.Time
}

func (d Date) MarshalJSON() ([]byte, error) {
    s := d.Format("2006-01-02")
    return []byte(`"` + s + `"`), nil
}

func (d *Date) UnmarshalJSON(data []byte) error {
    s := strings.Trim(string(data), `"`)
    t, err := time.Parse("2006-01-02", s)
    if err != nil {
        return err
    }
    d.Time = t
    return nil
}

