import "sync"

func worker(id int, wg *sync.WaitGroup) {
    defer wg.Done()  // tandai goroutine selesai
    fmt.Printf("Worker %d mulai\n", id)
    time.Sleep(time.Second)
    fmt.Printf("Worker %d selesai\n", id)
}

func main() {
    var wg sync.WaitGroup

    for i := 1; i <= 5; i++ {
        wg.Add(1)            // tambah counter
        go worker(i, &wg)
    }

    wg.Wait()                // block sampai semua Done
    fmt.Println("Semua worker selesai")
}

func main() {
    ch := make(chan string)

    go func() {
        ch <- "halo dari goroutine"  // kirim ke channel
    }()

    msg := <-ch                       // terima dari channel (blocking)
    fmt.Println(msg)
}

func produce(ch chan<- int) {
    for i := 0; i < 5; i++ {
        ch <- i
    }
    close(ch)  // beritahu receiver bahwa tidak ada data lagi
}

func main() {
    ch := make(chan int)
    go produce(ch)

    // range otomatis berhenti saat channel ditutup
    for n := range ch {
        fmt.Println(n)
    }
}

func main() {
    ch1 := make(chan string)
    ch2 := make(chan string)

    go func() { time.Sleep(1 * time.Second); ch1 <- "satu" }()
    go func() { time.Sleep(2 * time.Second); ch2 <- "dua" }()

    for i := 0; i < 2; i++ {
        select {
        case msg1 := <-ch1:
            fmt.Println("dari ch1:", msg1)
        case msg2 := <-ch2:
            fmt.Println("dari ch2:", msg2)
        case <-time.After(3 * time.Second):
            fmt.Println("timeout!")
            return
        }
    }
}

func worker(id int, jobs <-chan int, results chan<- int) {
    for j := range jobs {
        fmt.Printf("worker %d: job %d\n", id, j)
        time.Sleep(time.Second)
        results <- j * 2
    }
}

func main() {
    jobs := make(chan int, 100)
    results := make(chan int, 100)

    // 3 worker
    for w := 1; w <= 3; w++ {
        go worker(w, jobs, results)
    }

    // Kirim 9 job
    for j := 1; j <= 9; j++ {
        jobs <- j
    }
    close(jobs)

    // Ambil hasil
    for a := 1; a <= 9; a++ {
        <-results
    }
}

import "sync"

type SafeCounter struct {
    mu sync.Mutex
    v  map[string]int
}

func (c *SafeCounter) Inc(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.v[key]++
}

func (c *SafeCounter) Value(key string) int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.v[key]
}

import "context"

// Background: root context, tidak pernah cancel
ctx := context.Background()

// TODO: placeholder ketika belum yakin context apa yang dipakai
ctx := context.TODO()

// WithCancel: cancel manual
ctx, cancel := context.WithCancel(context.Background())
defer cancel()

// WithTimeout: cancel otomatis setelah durasi
ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
defer cancel()

// WithDeadline: cancel pada waktu tertentu
deadline := time.Now().Add(10 * time.Second)
ctx, cancel := context.WithDeadline(context.Background(), deadline)
defer cancel()

// WithValue: simpan nilai request-scoped
ctx := context.WithValue(context.Background(), "userID", 42)
userID := ctx.Value("userID").(int)

func ambilData(ctx context.Context, url string) (string, error) {
    req, _ := http.NewRequestWithContext(ctx, "GET", url, nil)

    resp, err := http.DefaultClient.Do(req)
    if err != nil {
        return "", err  // termasuk cancellation
    }
    defer resp.Body.Close()

    body, _ := io.ReadAll(resp.Body)
    return string(body), nil
}

func main() {
    ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
    defer cancel()

    data, err := ambilData(ctx, "https://api.example.com/slow")
    if err != nil {
        if ctx.Err() == context.DeadlineExceeded {
            log.Println("timeout!")
        }
        return
    }
    fmt.Println(data)
}

func worker(ctx context.Context) {
    for {
        select {
        case <-ctx.Done():
            fmt.Println("worker dibatalkan:", ctx.Err())
            return
        default:
            // kerja...
            time.Sleep(500 * time.Millisecond)
        }
    }
}

func main() {
    ctx, cancel := context.WithCancel(context.Background())

    go worker(ctx)

    time.Sleep(2 * time.Second)
    cancel()  // beri sinyal stop ke worker
    time.Sleep(time.Second)
}

