import "golang.org/x/sync/errgroup"

func ambilSemua(ctx context.Context, urls []string) error {
    g, ctx := errgroup.WithContext(ctx)
    for _, url := range urls {
        url := url
        g.Go(func() error {
            return ambil(ctx, url) // jika error, ctx dibatalkan
        })
    }
    return g.Wait() // mengembalikan error pertama (jika ada)
}

var ErrTidakDitemukan = errors.New("data tidak ditemukan") // sentinel

type ValidasiError struct{ Field string }                  // custom
func (e *ValidasiError) Error() string {
    return "field tidak valid: " + e.Field
}

func ambil(id int) error {
    if id == 0 {
        return fmt.Errorf("ambil id %d: %w", id, ErrTidakDitemukan) // wrap
    }
    return nil
}

func main() {
    err := ambil(0)
    if errors.Is(err, ErrTidakDitemukan) { // cek sentinel di rantai
        fmt.Println("tidak ada")
    }
    var ve *ValidasiError
    if errors.As(err, &ve) {               // ekstrak tipe error
        fmt.Println(ve.Field)
    }
}

