type Angka interface{ ~int | ~int64 | ~float64 }

func Jumlah[T Angka](items []T) T {
    var total T
    for _, v := range items {
        total += v
    }
    return total
}

// generik untuk tipe apa pun
func Map[T, U any](s []T, f func(T) U) []U {
    hasil := make([]U, len(s))
    for i, v := range s {
        hasil[i] = f(v)
    }
    return hasil
}

func main() {
    fmt.Println(Jumlah([]int{1, 2, 3}))      // 6
    fmt.Println(Jumlah([]float64{1.5, 2.5})) // 4
