type Server struct {
    port    int
    timeout time.Duration
}
type Opsi func(*Server)

func DenganPort(p int) Opsi               { return func(s *Server) { s.port = p } }
func DenganTimeout(t time.Duration) Opsi  { return func(s *Server) { s.timeout = t } }

func NewServer(opts ...Opsi) *Server {
    s := &Server{port: 8080, timeout: 30 * time.Second} // default
    for _, o := range opts {
        o(s)
    }
    return s
}

