import "iter"

// iterator yang menghasilkan kuadrat 0..n-1
func Kuadrat(n int) iter.Seq[int] {
    return func(yield func(int) bool) {
        for i := 0; i < n; i++ {
            if !yield(i * i) {
                return // hormati break
            }
        }
    }
}

func main() {
    for v := range Kuadrat(5) { // 0 1 4 9 16
        fmt.Println(v)
    }
}

