    "golang.org/x/crypto/bcrypt"
)

type UserUsecase struct {
    repo domain.UserRepository
}

func NewUserUsecase(r domain.UserRepository) *UserUsecase {
    return &UserUsecase{repo: r}
}

func (uc *UserUsecase) Register(ctx context.Context, name, email, pass string) (*domain.User, error) {
    // Cek duplikat
    if existing, _ := uc.repo.GetByEmail(ctx, email); existing != nil {
        return nil, domain.ErrEmailAlreadyExist
    }

    // Hash password
    hash, err := bcrypt.GenerateFromPassword([]byte(pass), bcrypt.DefaultCost)
    if err != nil { return nil, err }

    u := &domain.User{
        Name:     name,
        Email:    email,
        Password: string(hash),
    }
    if err := u.Validate(); err != nil { return nil, err }

    if err := uc.repo.Create(ctx, u); err != nil { return nil, err }
    return u, nil
}

func (uc *UserUsecase) GetByID(ctx context.Context, id int64) (*domain.User, error) {
    return uc.repo.GetByID(ctx, id)
}

