import pb "github.com/namamu/keuangan/gen"

// server kita HANYA mengimplementasi interface hasil generate.
type ServerKeuangan struct {
    pb.UnimplementedLayananKeuanganServer // forward-compat: wajib disisipkan
    svc *service.KeuanganService          // service LAMA kita, dipakai ulang!
}

func (s *ServerKeuangan) Tambah(ctx context.Context, in *pb.PermintaanTambah) (*pb.Transaksi, error) {
    // userID dari context (interceptor auth — bagian berikutnya)
    userID := ctx.Value(KunciUserID).(int64)
    t, err := s.svc.Tambah(ctx, userID, model.Transaksi{
        Jenis: in.Jenis, Deskripsi: in.Deskripsi, Jumlah: in.Jumlah,
    })
    if err != nil {
        if errors.Is(err, service.ErrValidasi) {
            return nil, status.Error(codes.InvalidArgument, err.Error())
        }
        return nil, status.Error(codes.Internal, "gagal")
    }
    return &pb.Transaksi{
        Id: t.ID, Jenis: t.Jenis, Deskripsi: t.Deskripsi,
        Jumlah: t.Jumlah, Tanggal: t.Tanggal.Format(time.RFC3339),
    }, nil
}

// di .proto:
rpc Ekspor(PermintaanList) returns (stream Transaksi);   // 'stream'!

// di server: kirim satu per satu tanpa menumpuk di memori
func (s *ServerKeuangan) Ekspor(in *pb.PermintaanList, srv pb.LayananKeuangan_EksporServer) error {
    daftar, err := s.svc.List(srv.Context(), in.UserId)
    if err != nil {
        return err
    }
    for _, t := range daftar {
        if err := srv.Send(toPB(t)); err != nil { // kirim ke aliran
            return err
        }
    }
    return nil // nil = aliran selesai
}

func AuthInterceptor(ctx context.Context, req any, info *grpc.UnaryServerInfo,
    handler grpc.UnaryHandler) (any, error) {

    // metadata gRPC = padanan header HTTP
    md, _ := metadata.FromIncomingContext(ctx)
    tokens := md.Get("authorization")
    if len(tokens) == 0 {
        return nil, status.Error(codes.Unauthenticated, "butuh token")
    }
    userID, err := verifikasiJWT(tokens[0]) // fungsi SAMA dari HTTP
    if err != nil {
        return nil, status.Error(codes.Unauthenticated, "token tidak valid")
    }
    ctx = context.WithValue(ctx, KunciUserID, userID) // pola SAMA
    return handler(ctx, req)
}

// main.go:
lis, _ := net.Listen("tcp", ":9090")
srv := grpc.NewServer(grpc.UnaryInterceptor(AuthInterceptor))
pb.RegisterLayananKeuanganServer(srv, &ServerKeuangan{svc: svc})
srv.Serve(lis)

