type OrderCreated struct {
    OrderID    string  `json:"order_id"`
    UserID     int64   `json:"user_id"`
    Total      float64 `json:"total"`
    OccurredAt string  `json:"occurred_at"`
}

func main() {
    conn, err := amqp.Dial("amqp://guest:guest@localhost:5672/")
    if err != nil {
        log.Fatal(err)
    }
    defer conn.Close()

    ch, err := conn.Channel()
    if err != nil {
        log.Fatal(err)
    }
    defer ch.Close()

    // deklarasi exchange itu idempoten - aman dipanggil tiap start
    err = ch.ExchangeDeclare(
        "orders", // nama
        "topic",  // tipe
        true,     // durable: bertahan setelah broker restart
        false, false, false, nil,
    )
    if err != nil {
        log.Fatal(err)
    }

    evt := OrderCreated{
        OrderID: "ord-1001", UserID: 42, Total: 250000,
        OccurredAt: time.Now().Format(time.RFC3339),
    }
    body, _ := json.Marshal(evt)

    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    err = ch.PublishWithContext(ctx,
        "orders",        // exchange
        "order.created", // routing key
        false, false,
        amqp.Publishing{
            ContentType:  "application/json",
            Body:         body,
            DeliveryMode: amqp.Persistent, // pesan ditulis ke disk
            MessageId:    evt.OrderID,     // berguna untuk idempotency
        },
    )
    if err != nil {
        log.Fatal(err)
    }
    log.Println("event order.created dipublikasikan")
}

package main

import (
    "encoding/json"
    "log"

    amqp "github.com/rabbitmq/amqp091-go"
)

func main() {
    conn, _ := amqp.Dial("amqp://guest:guest@localhost:5672/")
    defer conn.Close()
    ch, _ := conn.Channel()
    defer ch.Close()

    ch.ExchangeDeclare("orders", "topic", true, false, false, false, nil)

    // queue tahan-lama milik service notifikasi
    q, _ := ch.QueueDeclare("notifikasi", true, false, false, false, nil)

    // ikat queue ke exchange: hanya tertarik pada event order.created
    ch.QueueBind(q.Name, "order.created", "orders", false, nil)

    // QoS prefetch: jangan kirim >10 pesan belum-di-ack ke satu consumer.
    // Ini menyeimbangkan beban & mencegah satu consumer menimbun pesan.
    ch.Qos(10, 0, false)

    // autoAck=false: KITA yang memutuskan kapan pesan dianggap selesai
    msgs, _ := ch.Consume(q.Name, "", false, false, false, false, nil)

    log.Println("menunggu event... (CTRL+C untuk berhenti)")
    for d := range msgs {
        var evt OrderCreated
        if err := json.Unmarshal(d.Body, &evt); err != nil {
            // pesan rusak & tak mungkin sukses -> jangan requeue
            d.Nack(false, false) // requeue=false: buang / kirim ke DLX
            continue
        }

        if err := kirimEmail(evt); err != nil {
            log.Printf("gagal kirim, coba lagi: %v", err)
            d.Nack(false, true) // requeue=true: kembalikan ke queue
            continue
        }

        d.Ack(false) // sukses -> hapus permanen dari queue
        log.Printf("email terkirim untuk %s", evt.OrderID)
    }
}

// Jalankan binary consumer yang sama beberapa kali:
//   go run consumer/main.go   (instance #1)
//   go run consumer/main.go   (instance #2)
//   go run consumer/main.go   (instance #3)
//
// Ketiganya Consume dari queue "notifikasi" yang sama.
// RabbitMQ mengirim pesan ke salah satu yang menganggur (round-robin).
// Dengan ch.Qos(1, 0, false), pesan baru hanya dikirim ke worker yang
// sudah meng-ack pesan sebelumnya -> "fair dispatch" untuk tugas berat.

// Satu event "order.created" dikonsumsi banyak service sekaligus.
// Tiap service punya queue sendiri yang diikat ke exchange "orders":

// service notifikasi - hanya order.created
ch.QueueDeclare("notifikasi", true, false, false, false, nil)
ch.QueueBind("notifikasi", "order.created", "orders", false, nil)

// service inventaris - semua event order (wildcard)
ch.QueueDeclare("inventaris", true, false, false, false, nil)
ch.QueueBind("inventaris", "order.*", "orders", false, nil)  // * = satu kata

// service audit - SEMUA event apa pun (wildcard penuh)
ch.QueueDeclare("audit", true, false, false, false, nil)
ch.QueueBind("audit", "#", "orders", false, nil)  // # = nol/lebih kata

// Karena tiap service punya queue terpisah, semuanya menerima
// SALINAN sendiri dari order.created. Ini pola publish/subscribe.

// 1) buat exchange & queue penampung pesan mati
ch.ExchangeDeclare("orders.dlx", "fanout", true, false, false, false, nil)
ch.QueueDeclare("orders.dead", true, false, false, false, nil)
ch.QueueBind("orders.dead", "", "orders.dlx", false, nil)

// 2) queue utama menunjuk ke DLX lewat argumen
args := amqp.Table{
    "x-dead-letter-exchange": "orders.dlx",
    "x-message-ttl":          int32(60000), // opsional: mati setelah 60 dtk
}
ch.QueueDeclare("notifikasi", true, false, false, false, args)

// 3) di consumer, pesan yang mustahil sukses -> buang ke DLX:
//    d.Nack(false, false)  // requeue=false -> pindah ke orders.dead
//
// Operator lalu memeriksa orders.dead, memperbaiki masalah,
// dan (jika perlu) mempublish ulang pesan ke exchange utama.

