func main() {
    r := kafka.NewReader(kafka.ReaderConfig{
        Brokers: []string{"localhost:9092"},
        Topic:   "orders",
        GroupID: "service-notifikasi", // <- kunci consumer group
        // Anggota grup yang sama BERBAGI partition. Tambah instance =
        // tambah paralelisme, sampai sebanyak jumlah partition.
    })
    defer r.Close()

    log.Println("membaca dari topic orders...")
    for {
        // FetchMessage TIDAK auto-commit -> kita kontrol penuh (at-least-once)
        m, err := r.FetchMessage(context.Background())
        if err != nil {
            break
        }

        var evt OrderCreated
        if err := json.Unmarshal(m.Value, &evt); err != nil {
            log.Printf("pesan rusak di offset %d, lewati", m.Offset)
            r.CommitMessages(context.Background(), m) // akui & lewati
            continue
        }

        if err := kirimEmail(evt); err != nil {
            log.Printf("gagal proses, TIDAK commit (akan dibaca ulang): %v", err)
            continue // offset tak di-commit -> pesan diproses lagi nanti
        }

        // commit HANYA setelah sukses -> jaminan at-least-once
        r.CommitMessages(context.Background(), m)
        log.Printf("selesai offset %d untuk %s", m.Offset, evt.OrderID)
    }
}

// CHOREOGRAPHY - tiap service mendengar & bereaksi, tanpa bos pusat
// Order      --order.created-->  (Pembayaran mendengar)
// Pembayaran --payment.ok-->     (Inventaris & Notifikasi mendengar)
// Inventaris --stock.reserved--> (Pengiriman mendengar)
//
// Plus: sangat longgar-kopling, mudah tambah service baru.
// Minus: alur tersebar; sulit melihat "gambar besar" & men-debug.

// ORCHESTRATION - satu koordinator memanggil langkah berurutan
// Orchestrator: tagih -> jika ok, kurangi stok -> jika ok, kirim notif
//
// Plus: alur eksplisit di satu tempat, mudah dipahami.
// Minus: koordinator jadi titik pusat yang harus dijaga.

// Saga checkout (gaya choreography):
//   1. Buat order (status: PENDING)
//   2. Tagih pembayaran  --gagal?--> kompensasi: batalkan order
//   3. Kurangi stok       --gagal?--> kompensasi: refund + batalkan order
//   4. Set order COMPLETED

// Service Pembayaran mendengar order.created
func onOrderCreated(evt OrderCreated) {
    if err := tagih(evt.UserID, evt.Total); err != nil {
        publish("payment.failed", PaymentFailed{OrderID: evt.OrderID})
        return
    }
    publish("payment.succeeded", PaymentSucceeded{OrderID: evt.OrderID})
}

// Service Order mendengar payment.failed -> jalankan KOMPENSASI
func onPaymentFailed(evt PaymentFailed) {
    setStatus(evt.OrderID, "CANCELLED") // batalkan; tak ada uang ditahan
    log.Printf("order %s dibatalkan: pembayaran gagal", evt.OrderID)
}

// LANGKAH 1: simpan order + event dalam SATU transaksi DB (atomik)
func buatOrder(ctx context.Context, db *sql.DB, o Order) error {
    tx, err := db.BeginTx(ctx, nil)
    if err != nil {
        return err
    }
    defer tx.Rollback()

    if _, err := tx.ExecContext(ctx,
        `INSERT INTO orders(id, user_id, total, status)
         VALUES($1,$2,$3,'PENDING')`,
        o.ID, o.UserID, o.Total); err != nil {
        return err
    }

    payload, _ := json.Marshal(OrderCreated{OrderID: o.ID, UserID: o.UserID, Total: o.Total})
    if _, err := tx.ExecContext(ctx,
        `INSERT INTO outbox(topic, payload, status)
         VALUES('order.created', $1, 'NEW')`,
        payload); err != nil {
        return err
    }
    return tx.Commit() // order & event tersimpan bersama, atau tidak sama sekali
}

// LANGKAH 2: proses relay terpisah membaca outbox & publish ke broker
func relayOutbox(ctx context.Context, db *sql.DB, broker Broker) {
    rows, _ := db.QueryContext(ctx,
        `SELECT id, topic, payload FROM outbox WHERE status='NEW' LIMIT 100`)
    defer rows.Close()
    for rows.Next() {
        var id int64; var topic string; var payload []byte
        rows.Scan(&id, &topic, &payload)
        if err := broker.Publish(topic, payload); err != nil {
            continue // gagal -> biarkan 'NEW', coba lagi siklus berikutnya
        }
        db.ExecContext(ctx, `UPDATE outbox SET status='SENT' WHERE id=$1`, id)
    }
}

func prosesIdempoten(ctx context.Context, db *sql.DB, evt OrderCreated) error {
    // coba klaim event ini; jika sudah ada, berarti duplikat
    res, err := db.ExecContext(ctx,
        `INSERT INTO processed_events(event_id) VALUES($1)
         ON CONFLICT (event_id) DO NOTHING`,
        evt.OrderID)
    if err != nil {
        return err
    }
    if n, _ := res.RowsAffected(); n == 0 {
        log.Printf("event %s sudah diproses, lewati (duplikat)", evt.OrderID)
        return nil // aman: tidak melakukan efek samping dua kali
    }
    return kirimEmail(evt) // baru pertama kali -> kerjakan efeknya
}

func prosesDenganRetry(evt OrderCreated) error {
    const maksPercobaan = 3
    var err error
    for i := 0; i < maksPercobaan; i++ {
        if err = kirimEmail(evt); err == nil {
            return nil // sukses
        }
        // jeda makin lama: 1s, 2s, 4s ... (exponential backoff)
        time.Sleep(time.Duration(1<<i) * time.Second)
    }
    // habis jatah -> kembalikan error agar dipindah ke dead-letter
    return fmt.Errorf("gagal setelah %d percobaan: %w", maksPercobaan, err)
}

// Consumer wajib berhenti dengan rapi: selesaikan pesan yang
// sedang diproses, lalu commit/ack, baru keluar. Jangan putus di tengah.
func jalankanConsumer(ctx context.Context, r *kafka.Reader) {
    for {
        select {
        case <-ctx.Done(): // sinyal stop (SIGTERM dari Kubernetes)
            log.Println("shutdown: menutup reader...")
            r.Close()
            return
        default:
            m, err := r.FetchMessage(ctx)
            if err != nil {
                return
            }
            if err := proses(m); err == nil {
                r.CommitMessages(ctx, m)
            }
        }
    }
}

// di main: hubungkan sinyal OS ke context (lihat Bagian V, graceful shutdown)
ctx, stop := signal.NotifyContext(context.Background(),
    syscall.SIGINT, syscall.SIGTERM)
defer stop()
jalankanConsumer(ctx, reader)

