package repository

import (
    "context"
    "errors"
    "sync"
    "time"

    "github.com/namamu/keuangan-api/internal/model"
)

var ErrTidakDitemukan = errors.New("transaksi tidak ditemukan")

// Kontrak yang harus dipenuhi semua penyimpanan
type TransaksiRepo interface {
    List(ctx context.Context) ([]model.Transaksi, error)
    Create(ctx context.Context, t model.Transaksi) (model.Transaksi, error)
    Update(ctx context.Context, t model.Transaksi) (model.Transaksi, error)
    Delete(ctx context.Context, id int64) error
}

type MemoryRepo struct {
    mu     sync.RWMutex
    data   map[int64]model.Transaksi
    nextID int64
}

func NewMemoryRepo() *MemoryRepo {
    return &MemoryRepo{data: make(map[int64]model.Transaksi), nextID: 1}
}

func (r *MemoryRepo) List(ctx context.Context) ([]model.Transaksi, error) {
    r.mu.RLock()
    defer r.mu.RUnlock()
    out := make([]model.Transaksi, 0, len(r.data))
    for _, t := range r.data {
        out = append(out, t)
    }
    return out, nil
}

func (r *MemoryRepo) Create(ctx context.Context, t model.Transaksi) (model.Transaksi, error) {
    r.mu.Lock()
    defer r.mu.Unlock()
    t.ID = r.nextID
    t.Tanggal = time.Now()
    r.nextID++
    r.data[t.ID] = t
    return t, nil
}

func (r *MemoryRepo) Update(ctx context.Context, t model.Transaksi) (model.Transaksi, error) {
    r.mu.Lock()
    defer r.mu.Unlock()
    lama, ada := r.data[t.ID]
    if !ada {
        return model.Transaksi{}, ErrTidakDitemukan
    }
    t.Tanggal = lama.Tanggal
    r.data[t.ID] = t
    return t, nil
}

func (r *MemoryRepo) Delete(ctx context.Context, id int64) error {
    r.mu.Lock()
    defer r.mu.Unlock()
    if _, ada := r.data[id]; !ada {
        return ErrTidakDitemukan
    }
    delete(r.data, id)
    return nil
}

package service

import (
    "context"
    "errors"
    "strings"

    "github.com/namamu/keuangan-api/internal/model"
    "github.com/namamu/keuangan-api/internal/repository"
)

var ErrValidasi = errors.New("data transaksi tidak valid")

type KeuanganService struct {
    repo repository.TransaksiRepo
}

func New(repo repository.TransaksiRepo) *KeuanganService {
    return &KeuanganService{repo: repo}
}

func (s *KeuanganService) Daftar(ctx context.Context) ([]model.Transaksi, error) {
    return s.repo.List(ctx)
}

func (s *KeuanganService) Tambah(ctx context.Context, t model.Transaksi) (model.Transaksi, error) {
    if err := validasi(t); err != nil {
        return model.Transaksi{}, err
    }
    return s.repo.Create(ctx, t)
}

func (s *KeuanganService) Ubah(ctx context.Context, t model.Transaksi) (model.Transaksi, error) {
    if err := validasi(t); err != nil {
        return model.Transaksi{}, err
    }
    return s.repo.Update(ctx, t)
}

func (s *KeuanganService) Hapus(ctx context.Context, id int64) error {
    return s.repo.Delete(ctx, id)
}

func (s *KeuanganService) Ringkasan(ctx context.Context) (model.Ringkasan, error) {
    list, err := s.repo.List(ctx)
    if err != nil {
        return model.Ringkasan{}, err
    }
    var r model.Ringkasan
    for _, t := range list {
        if t.Jenis == model.Pemasukan {
            r.Pemasukan += t.Jumlah
        } else {
            r.Pengeluaran += t.Jumlah
        }
    }
    r.Saldo = r.Pemasukan - r.Pengeluaran
    return r, nil
}

func validasi(t model.Transaksi) error {
    if strings.TrimSpace(t.Deskripsi) == "" {
        return errors.Join(ErrValidasi, errors.New("deskripsi wajib diisi"))
    }
    if t.Jumlah <= 0 {
        return errors.Join(ErrValidasi, errors.New("jumlah harus lebih dari 0"))
    }
    if !t.Jenis.Valid() {
        return errors.Join(ErrValidasi, errors.New("jenis tidak dikenal"))
    }
    return nil
}

