import (
    "context"
    "encoding/json"
    "errors"
    "net/http"
    "strconv"

    "github.com/namamu/keuangan-api/internal/model"
    "github.com/namamu/keuangan-api/internal/repository"
    "github.com/namamu/keuangan-api/internal/service"
)

type TransaksiHandler struct {
    svc *service.KeuanganService
}

func New(svc *service.KeuanganService) *TransaksiHandler {
    return &TransaksiHandler{svc: svc}
}

// Routes mendaftarkan semua endpoint (pola Go 1.22: method + path)
func (h *TransaksiHandler) Routes(mux *http.ServeMux) {
    mux.HandleFunc("GET /api/transaksi", h.daftar)
    mux.HandleFunc("POST /api/transaksi", h.tambah)
    mux.HandleFunc("PUT /api/transaksi/{id}", h.ubah)
    mux.HandleFunc("DELETE /api/transaksi/{id}", h.hapus)
    mux.HandleFunc("GET /api/ringkasan", h.ringkasan)
}

func tulisJSON(w http.ResponseWriter, status int, data any) {
    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(status)
    json.NewEncoder(w).Encode(data)
}

func tulisError(w http.ResponseWriter, status int, pesan string) {
    tulisJSON(w, status, map[string]string{"error": pesan})
}

func (h *TransaksiHandler) daftar(w http.ResponseWriter, r *http.Request) {
    list, err := h.svc.Daftar(r.Context())
    if err != nil {
        tulisError(w, http.StatusInternalServerError, "gagal mengambil data")
        return
    }
    tulisJSON(w, http.StatusOK, list)
}

func (h *TransaksiHandler) tambah(w http.ResponseWriter, r *http.Request) {
    var t model.Transaksi
    if err := json.NewDecoder(r.Body).Decode(&t); err != nil {
        tulisError(w, http.StatusBadRequest, "JSON tidak valid")
        return
    }
    dibuat, err := h.svc.Tambah(r.Context(), t)
    if err != nil {
        if errors.Is(err, service.ErrValidasi) {
            tulisError(w, http.StatusBadRequest, err.Error())
            return
        }
        tulisError(w, http.StatusInternalServerError, "gagal menyimpan")
        return
    }
    tulisJSON(w, http.StatusCreated, dibuat)
}

func (h *TransaksiHandler) ubah(w http.ResponseWriter, r *http.Request) {
    id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
    if err != nil {
        tulisError(w, http.StatusBadRequest, "id tidak valid")
        return
    }
    var t model.Transaksi
    if err := json.NewDecoder(r.Body).Decode(&t); err != nil {
        tulisError(w, http.StatusBadRequest, "JSON tidak valid")
        return
    }
    t.ID = id
    hasil, err := h.svc.Ubah(r.Context(), t)
    if err != nil {
        if errors.Is(err, repository.ErrTidakDitemukan) {
            tulisError(w, http.StatusNotFound, "transaksi tidak ditemukan")
            return
        }
        tulisError(w, http.StatusBadRequest, err.Error())
        return
    }
    tulisJSON(w, http.StatusOK, hasil)
}

func (h *TransaksiHandler) hapus(w http.ResponseWriter, r *http.Request) {
    id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
    if err != nil {
        tulisError(w, http.StatusBadRequest, "id tidak valid")
        return
    }
    if err := h.svc.Hapus(r.Context(), id); err != nil {
        if errors.Is(err, repository.ErrTidakDitemukan) {
            tulisError(w, http.StatusNotFound, "tidak ditemukan")
            return
        }
        tulisError(w, http.StatusInternalServerError, "gagal menghapus")
        return
    }
    w.WriteHeader(http.StatusNoContent)
}

func (h *TransaksiHandler) ringkasan(w http.ResponseWriter, r *http.Request) {
    rk, err := h.svc.Ringkasan(r.Context())
    if err != nil {
        tulisError(w, http.StatusInternalServerError, "gagal hitung")
        return
    }
    tulisJSON(w, http.StatusOK, rk)
}

// dekodeJSON membatasi ukuran body & menolak field tak dikenal.
func dekodeJSON(w http.ResponseWriter, r *http.Request, tujuan any) error {
    r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // batas 1 MB
    dec := json.NewDecoder(r.Body)
    dec.DisallowUnknownFields() // tolak field asing -> cegah typo & payload jahat
    return dec.Decode(tujuan)
}

