import (
    "log/slog"
    "net/http"
    "time"
)

// CORS: izinkan front-end React mengakses API
func CORS(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Access-Control-Allow-Origin", "http://localhost:5173")
        w.Header().Set("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE,OPTIONS")
        w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
        if r.Method == http.MethodOptions {
            w.WriteHeader(http.StatusNoContent) // preflight
            return
        }
        next.ServeHTTP(w, r)
    })
}

func Logging(logger *slog.Logger) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            mulai := time.Now()
            next.ServeHTTP(w, r)
            logger.Info("request", "method", r.Method,
                "path", r.URL.Path, "durasi", time.Since(mulai).String())
        })
    }
}

func Recover(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if rec := recover(); rec != nil {
                http.Error(w, "kesalahan server", http.StatusInternalServerError)
            }
        }()
        next.ServeHTTP(w, r)
    })
}

