package repository

import (
    "context"
    "database/sql"
    "time"

    "github.com/namamu/keuangan-api/internal/model"
    _ "modernc.org/sqlite"
)

type SQLiteRepo struct{ db *sql.DB }

func NewSQLiteRepo(path string) (*SQLiteRepo, error) {
    db, err := sql.Open("sqlite", path)
    if err != nil {
        return nil, err
    }
    _, err = db.Exec(`CREATE TABLE IF NOT EXISTS transaksi (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        jenis TEXT NOT NULL,
        deskripsi TEXT NOT NULL,
        jumlah REAL NOT NULL,
        tanggal DATETIME NOT NULL
    )`)
    if err != nil {
        return nil, err
    }
    return &SQLiteRepo{db: db}, nil
}

func (r *SQLiteRepo) List(ctx context.Context) ([]model.Transaksi, error) {
    rows, err := r.db.QueryContext(ctx,
        "SELECT id, jenis, deskripsi, jumlah, tanggal FROM transaksi ORDER BY id DESC")
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    var out []model.Transaksi
    for rows.Next() {
        var t model.Transaksi
        if err := rows.Scan(&t.ID, &t.Jenis, &t.Deskripsi, &t.Jumlah, &t.Tanggal); err != nil {
            return nil, err
        }
        out = append(out, t)
    }
    return out, rows.Err()
}

func (r *SQLiteRepo) Create(ctx context.Context, t model.Transaksi) (model.Transaksi, error) {
    t.Tanggal = time.Now()
    res, err := r.db.ExecContext(ctx,
        "INSERT INTO transaksi (jenis, deskripsi, jumlah, tanggal) VALUES (?, ?, ?, ?)",
        t.Jenis, t.Deskripsi, t.Jumlah, t.Tanggal)
    if err != nil {
        return model.Transaksi{}, err
    }
    t.ID, _ = res.LastInsertId()
    return t, nil
}

func (r *SQLiteRepo) Update(ctx context.Context, t model.Transaksi) (model.Transaksi, error) {
    res, err := r.db.ExecContext(ctx,
        "UPDATE transaksi SET jenis=?, deskripsi=?, jumlah=? WHERE id=?",
        t.Jenis, t.Deskripsi, t.Jumlah, t.ID)
    if err != nil {
        return model.Transaksi{}, err
    }
    if n, _ := res.RowsAffected(); n == 0 {
        return model.Transaksi{}, ErrTidakDitemukan
    }
    return t, nil
}

func (r *SQLiteRepo) Delete(ctx context.Context, id int64) error {
    res, err := r.db.ExecContext(ctx, "DELETE FROM transaksi WHERE id=?", id)
    if err != nil {
        return err
    }
    if n, _ := res.RowsAffected(); n == 0 {
        return ErrTidakDitemukan
    }
    return nil
}

