package handler

import (
    "context"
    "log/slog"
    "net/http"
    "github.com/google/uuid"
)

type ctxKey string

const KunciReqID ctxKey = "req_id"

// RequestID menyuntik ID unik ke tiap request agar mudah dilacak di log.
func RequestID(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        id := r.Header.Get("X-Request-ID")
        if id == "" {
            id = uuid.NewString()
        }
        w.Header().Set("X-Request-ID", id)
        ctx := context.WithValue(r.Context(), KunciReqID, id)
        next.ServeHTTP(w, r.WithContext(ctx))
    })
}

// LoggingKaya mencatat status code dan request id (pakai pembungkus ResponseWriter).
func LoggingKaya(logger *slog.Logger) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            sw := &statusWriter{ResponseWriter: w, status: 200}
            next.ServeHTTP(sw, r)
            reqID, _ := r.Context().Value(KunciReqID).(string)
            logger.Info("request",
                "req_id", reqID,
                "method", r.Method,
                "path", r.URL.Path,
                "status", sw.status)
        })
    }
}

type statusWriter struct {
    http.ResponseWriter
    status int
}

func (s *statusWriter) WriteHeader(code int) {
    s.status = code
    s.ResponseWriter.WriteHeader(code)
}

