package handler

import (
    "net/http"
    "sync"

    "golang.org/x/time/rate"
)

// Pembatas laju sederhana per alamat IP (token bucket).
type RateLimiter struct {
    mu       sync.Mutex
    pelanggan map[string]*rate.Limiter
    rps      rate.Limit
    burst    int
}

func NewRateLimiter(rps float64, burst int) *RateLimiter {
    return &RateLimiter{
        pelanggan: make(map[string]*rate.Limiter),
        rps:       rate.Limit(rps),
        burst:     burst,
    }
}

func (rl *RateLimiter) ambil(ip string) *rate.Limiter {
    rl.mu.Lock()
    defer rl.mu.Unlock()
    l, ada := rl.pelanggan[ip]
    if !ada {
        l = rate.NewLimiter(rl.rps, rl.burst)
        rl.pelanggan[ip] = l
    }
    return l
}

func (rl *RateLimiter) Middleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        if !rl.ambil(r.RemoteAddr).Allow() {
            http.Error(w, "terlalu banyak permintaan", http.StatusTooManyRequests)
            return
        }
        next.ServeHTTP(w, r)
    })
}

func (uc *OrderUsecase) Checkout(ctx context.Context, userID int64) (*domain.Order, error) {
    var order *domain.Order

    err := uc.tx.WithTx(ctx, func(ctx context.Context) error {
        // 1. Ambil cart
        items, err := uc.cartRepo.GetByUser(ctx, userID)
        if err != nil { return err }
        if len(items) == 0 { return domain.ErrEmptyCart }

        // 2. Hitung total + cek stock + lock row
        var total decimal.Decimal
        for _, item := range items {
            p, err := uc.productRepo.GetByIDForUpdate(ctx, item.ProductID) // SELECT ... FOR UPDATE
            if err != nil { return err }
            if p.Stock < item.Quantity {
                return fmt.Errorf("stock %s tidak cukup", p.Name)
            }
            total = total.Add(p.Price.Mul(decimal.NewFromInt(int64(item.Quantity))))

            // Kurangi stock
            if err := uc.productRepo.DecrementStock(ctx, p.ID, item.Quantity); err != nil {
                return err
            }
        }

        // 3. Buat order
        order = &domain.Order{
            UserID: userID,
            Total:  total,
            Status: "pending",
        }
        if err := uc.orderRepo.Create(ctx, order, items); err != nil { return err }

        // 4. Kosongkan cart
        if err := uc.cartRepo.ClearByUser(ctx, userID); err != nil { return err }

        return nil
    })

    if err != nil { return nil, err }

    // 5. Publish event ke message queue (async)
    uc.publisher.Publish(ctx, "order.created", order)

    return order, nil
}

type Pagination struct {
    Page    int   `form:"page" binding:"min=1"`
    Limit   int   `form:"limit" binding:"min=1,max=100"`
    Total   int64 `json:"total"`
    Pages   int   `json:"pages"`
}

func (p *Pagination) Offset() int {
    return (p.Page - 1) * p.Limit
}

func (p *Pagination) SetTotal(t int64) {
    p.Total = t
    p.Pages = int((t + int64(p.Limit) - 1) / int64(p.Limit))
}

// Handler
func (h *ProductHandler) List(c *gin.Context) {
