    c.ShouldBindQuery(p)

    products, total, _ := h.uc.List(c.Request.Context(), p.Limit, p.Offset())
    p.SetTotal(total)

    c.JSON(200, gin.H{
        "data":       products,
        "pagination": p,
    })
}

