package main

import (
    "context"
    "log"
    "time"

    "google.golang.org/grpc"
    "google.golang.org/grpc/credentials/insecure"
    pb "github.com/daniel/myapp/proto/user"
)

func main() {
    conn, err := grpc.NewClient("localhost:50051",
        grpc.WithTransportCredentials(insecure.NewCredentials()))
    if err != nil { log.Fatalf("dial: %v", err) }
    defer conn.Close()

    client := pb.NewUserServiceClient(conn)

    // Unary call
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    user, err := client.GetUser(ctx, &pb.GetUserRequest{Id: 1})
    if err != nil { log.Fatalf("GetUser: %v", err) }
    log.Printf("User: %+v", user)

    // Server streaming
    stream, _ := client.StreamUsers(ctx, &pb.StreamUsersRequest{})
    for {
        u, err := stream.Recv()
        if err != nil { break }
        log.Printf("Stream: %+v", u)
    }
}

func loggingInterceptor(
    ctx context.Context,
    req interface{},
    info *grpc.UnaryServerInfo,
    handler grpc.UnaryHandler,
) (interface{}, error) {
    start := time.Now()
    resp, err := handler(ctx, req)
    log.Printf("%s took %v err=%v", info.FullMethod, time.Since(start), err)
    return resp, err
}

s := grpc.NewServer(
    grpc.UnaryInterceptor(loggingInterceptor),
)

